"""Explicit, lossless-intent manual-to-contract migration scaffold. Never silently declares approval."""
import pathlib,json,datetime
from .qa import static_audit
from .validate import build_hash

def scaffold(site_root,project,kind,output_dir):
    site_root=pathlib.Path(site_root).resolve();out=pathlib.Path(output_dir).resolve();out.mkdir(parents=True,exist_ok=True)
    is_fin=project.lower()=='diboas';s=static_audit(site_root);files=s['files'];h=s['source_hash']
    from .qa import audit
    qr=audit(site_root,site_root/'.web_mvp_v02_qa')
    assets=[]
    for p in sorted((site_root/'assets').rglob('*')) if (site_root/'assets').exists() else []:
        if p.is_file():assets.append({'path':str(p.relative_to(site_root)),'origin':'reused_asset_from_original_pilot_archive','approval':'LEGACY','rights':'UNKNOWN','use_scope':'private_preview_only'})
    sect=[{'id':a,'purpose':'Existing pilot section; not independently approved'} for a in (['inicio','explorar','practice'] if is_fin else ['main','collection','croissant','details','contact'])]
    q={'schema_version':'0.2.0','route':'WEB_PREVIEW','mode':'FAST','project':project,'build_version':'0.1-pilot-source-reassessment','state':'PREVIEW_DRAFT','verdict':'PARTIAL','execution':{'execution_mode':'MANUAL_SPEC_GUIDED','skill_package_version':'WEB_MVP_v0.1_spec_applied_manually','methods':[{'name':'WEB_EXPERIENCE_v0.1_design_spec','state':'DOCUMENTED'},{'name':'Sites_support_from_original_Work','state':'DOCUMENTED'}],'tools':['legacy_HTML_CSS_JS','standalone_v0.2_static_validator'],'paid_authorized':False,'public_deploy_authorized':False,'activation_evidence':None},
      'WEB_BRIEF':{'deliverable_scope':'Private pilot website from archived Work output','business_kind':kind,'user_goal':'Reassess existing preview for schema compliance','audience_basis':'Original project brief; independently re-approve','product_service_truth_refs':['Pilot ZIP linked in independent audit; not product canon'],'known_unknown_boundary':['No user-approved design, legal or conversion claims','Preview may not persist outside host'],'brand_authority_state':'EXISTING_MIXED','primary_action_intent':'Explore local website without publication','task_completion_condition':'Valid typed record plus scoped QA','current_brand_refs':['Existing project documentation; authority unchanged'],**({'regulated_claim_boundary':'Local educational financial illustration only; no licensed banking product inferred'} if is_fin else {'product_material_scale_truth_state':'Physical product appearances sourced from photographs; pricing/material specifications unconfirmed'}),'proposed_function_hypothesis':'Local goal exploration is not canonical Practice' if is_fin else 'Six-product editorial browsing is a provisional layout'},
      'WEB_DIRECTION':{'value_proposition':'Life-first goal exploration (provisional)' if is_fin else 'Everyday accessories editorial exploration (provisional)','primary_cta_intent':'Explore local calculation' if is_fin else 'Explore collection and existing Instagram','sections_and_purpose':sect,'visual_direction':'Existing pilot visual design, still provisional','creative_open_zones':['copy','layout','illustration choices'],'brand_alignment':'Legacy and provisional references require review','claim_and_offer_boundaries':'No inferred prices, guarantees, launch states or verified service claims','motion_fallback_and_controls':'CSS declares reduced-motion fallback; browser execution not yet verified'},
      'WEB_ASSET_PLAN':{'assets_used':assets,'asset_authority_and_rights':'Sources from project pilot; rights not independently cleared','generation_required_decision':'No new image generation required for schema pilot','product_identity_preservation':'Existing images not changed','provisional_vs_approved_labels':'Everything in preview provisional until user approval'},
      'WEB_PREVIEW_BUILD':{'preview_status':'AVAILABLE_UNVERIFIED','source_files':files,'verified_preview_ref_or_local_open_instructions':'Use bundled helper: python -m runtime.cli preview start SITE_ROOT; URL limited to loopback','responsive_strategy':'Original CSS available; runtime browser test status recorded separately','working_interactions':['Existing controls require fresh browser re-validation'],'primary_cta_behavior':'SAFE_LOCAL_DEMO' if is_fin else 'REAL_VERIFIED_LINK','real_vs_mock_integrations':'Local arithmetic; no real money flow' if is_fin else 'External Instagram link; no checkout or submission','version_id':'reassessment_v02','form_mode':'LOCAL_CALCULATION' if is_fin else 'NONE','form_destination':None,'prefers_reduced_motion_fallback':'CSS declares fallback; runtime not yet validated','external_link_targets':s['external_links'],'preview_lifecycle_ref':None},
      'WEB_QA':{'checks':qr['checks'],'known_limitations':qr['limits']+([qr['browser_blocker']] if qr['browser_blocker'] else []),'verdict':'PARTIAL'}}
    (out/f'{project}_migrated_v02.json').write_text(json.dumps(q,ensure_ascii=False,indent=2))
    return q
